const previo = $('When Executed by Another Workflow').first().json;
const mensaje = previo.mensaje;

const meses = { enero:'01', febrero:'02', marzo:'03', abril:'04', mayo:'05', junio:'06', julio:'07', agosto:'08', septiembre:'09', octubre:'10', noviembre:'11', diciembre:'12' };

function resolverAnio(mes, dia, anioExplicito) {
  if (anioExplicito) return anioExplicito;
  const hoy = new Date();
  let anio = hoy.getFullYear();
  const candidata = new Date(`${anio}-${mes}-${dia}`);
  if (candidata < hoy) anio += 1;
  return String(anio);
}

const matchFecha = mensaje.match(/(\d{1,2})\s+de\s+(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre)(?:\s+de\s+(\d{4}))?/i);
let matchHora = mensaje.match(/a las\s+(\d{1,2})(?::(\d{2}))?/i);
if (!matchHora) { matchHora = mensaje.match(/\b(\d{1,2}):(\d{2})\b/); }

let fecha = '', hora = '';

if (matchFecha) {
  const dia = matchFecha[1].padStart(2, '0');
  const mes = meses[matchFecha[2].toLowerCase()];
  const anio = resolverAnio(mes, dia, matchFecha[3]);
  fecha = `${anio}-${mes}-${dia}`;
}

if (matchHora) {
  const h = matchHora[1].padStart(2, '0');
  const m = (matchHora[2] || '00').padStart(2, '0');
  hora = `${h}:${m}`;
}

let titulo = mensaje;
if (matchFecha) titulo = titulo.replace(matchFecha[0], '');
if (matchHora) titulo = titulo.replace(matchHora[0], '');
titulo = titulo.replace(/\b(apunta(lo)?|agendame|agenda|pon en el calendario que|pon en el calendario|crea un evento|a(n|ñ)ade|anota)\b/gi, '');
titulo = titulo.replace(/^[\s,:.;-]+|[\s,:.;-]+$/g, '').trim();
titulo = titulo.replace(/^(para|de|el|la)\s+/i, '').trim();
if (!titulo) titulo = 'Evento';
titulo = titulo.charAt(0).toUpperCase() + titulo.slice(1);

return [{ json: { usuario_id: previo.usuario_id, chat_id: previo.chat_id, fecha, hora, titulo } }];

const previo = $('Parsear evento').first().json;
const eventos = $input.all().map(i => i.json).filter(e => e.start);
const nuevoInicio = new Date(`${previo.fecha}T${previo.hora}:00`);
const nuevoFin = new Date(nuevoInicio.getTime() + 60*60*1000);

let conflicto = null;
for (const ev of eventos) {
  const evInicio = new Date(ev.start.dateTime || ev.start.date);
  const evFin = new Date(ev.end.dateTime || ev.end.date);
  if (nuevoInicio < evFin && nuevoFin > evInicio) { conflicto = ev.summary || '(sin titulo)'; break; }
}

return [{ json: { ...previo, hay_conflicto: !!conflicto, titulo_conflicto: conflicto || '' } }];

